def signals(history):
    pick=[]
    for ticker,bars in history.items():
        c=[row["close"] for row in bars]
        if len(c)<15:
            continue
        changes=[c[j]-c[j-1] for j in range(len(c)-14,len(c))]
        gain=sum(max(v,0.0) for v in changes)/14.0
        loss=sum(max(-v,0.0) for v in changes)/14.0
        rsi=100.0 if loss==0 else 100.0*gain/(gain+loss)
        if rsi<30.0:
            pick.append(ticker)
    return {t:1.0/len(pick) for t in pick} if pick else {}

