    def ema(xs,n):
        a=2.0/(n+1)
        v=xs[0]
        out=[]
        for x in xs:
            v=a*x+(1-a)*v
            out.append(v)
        return out
    chosen=[]
    for ticker,bars in history.items():
        c=[row["close"] for row in bars]
        if len(c)<40:
            continue
        f=ema(c,12)
        s=ema(c,26)
        mac=[x-y for x,y in zip(f,s)]
        sig=ema(mac,9)
        if mac[-1]>sig[-1] and c[-1]>s[-1]:
            chosen.append(ticker)
