def signals(history):
    raw={}
    for ticker,bars in history.items():
        c=[row["close"] for row in bars]
        if len(c)<61 or c[-61]<=0:
            continue
        if c[-1]/c[-61]-1 <= 0:
            continue
        r=[c[j]/c[j-1]-1 for j in range(len(c)-20,len(c))]
        avg=sum(r)/20.0
        vol=(sum((z-avg)**2 for z in r)/19.0)**0.5
        raw[ticker]=min(1.0,0.12/(vol*252**0.5)) if vol>0 else 0.0
    gross=sum(abs(w) for w in raw.values())
    return {t:w/max(1.0,gross) for t,w in raw.items() if w>0}

